    historySummary: "স্কেলটি ১৭৩০ সালে অনুরূপ একটি পদ্ধতি প্রথম প্রস্তাবকারী ফরাসি বিজ্ঞানী রনে আঁতোয়ান ফের্শো দ্য রেওমুরের নাম বহন করে। রেওমুরের মূল নকশায় লঘু অ্যালকোহল ব্যবহৃত হতো এবং প্রতি ডিগ্রি থার্মোমিটার আধারের আয়তনের হাজার ভাগের এক ভাগের সমান ছিল; পানির হিমাঙ্ক ও স্ফুটনাঙ্ক যথাক্রমে ০ ও ৮০ ডিগ্রি হিসেবে সংজ্ঞায়িত হয়। স্কেলটি বিশেষত ফ্রান্স, জার্মানি ও রাশিয়ায় ব্যাপকভাবে ব্যবহৃত হতো -- এমনকি তলস্তয় ও দস্তয়েভস্কির মতো লেখকদের রচনাতেও এর উল্লেখ পাওয়া যায়। ১৭৯০-এর দশকে ফ্রান্স মেট্রিক পদ্ধতির অংশ হিসেবে সেলসিয়াস স্কেলে চলে গেলে রেওমুর পরিত্যক্ত হয়, তবে ইউরোপের কিছু অঞ্চলে ১৯ শতকের মাঝামাঝি পর্যন্ত, রাশিয়ার কিছু অংশে ২০ শতকের শুরু পর্যন্ত ব্যবহৃত হতে থাকে। বর্তমানে এর ব্যবহার মূলত ইতালি, সুইজারল্যান্ড ও নেদারল্যান্ডসের কিছু খাদ্য উৎপাদন (বিশেষত পনির ও মিষ্টান্ন) প্রক্রিয়ার সাথে সীমাবদ্ধ।",
