export function findBengaliUnitPageBySourceSlug(sourceSlug: string) {
  return bengaliUnitPages.find((page) => page.sourceSlug === sourceSlug);
}

export function findBengaliUnitPage(category: string, unit: string) {
  return bengaliUnitPages.find(
    (page) => page.category === category && page.unit === unit
  );
}
